import test from 'node:test';
import assert from 'node:assert/strict';
import { setupHarness } from '../../../apps/platform-api/test/helpers/harness.ts';

test('serviceMenuItem: viewer can list, cannot create -> 403 TOKEN_SCOPE_MISMATCH', async () => {
  const harness = await setupHarness('demo');
  const viewer = await harness.asRole('viewer');

  const listRes = await viewer.request('GET', '/v1/apps/demo/service-menu-items');
  assert.equal(listRes.status, 200);

  const createRes = await viewer.request('POST', '/v1/apps/demo/service-menu-items', {
    name: 'Quick Trim',
    durationMinutes: 15,
  });
  assert.equal(createRes.status, 403);
  assert.equal(createRes.body.code, 'TOKEN_SCOPE_MISMATCH');
  await harness.close();
});

test('serviceMenuItem: owner create -> get -> patch -> archive round trip', async () => {
  const harness = await setupHarness('demo');
  const owner = await harness.asRole('owner');

  const createRes = await owner.request('POST', '/v1/apps/demo/service-menu-items', {
    name: 'Full Styling',
    durationMinutes: 45,
    priceMinor: 5000,
    tags: ['hair', 'styling'],
  });
  assert.equal(createRes.status, 200);
  const id = createRes.body.result.id;
  assert.ok(id);

  const getRes = await owner.request('GET', `/v1/apps/demo/service-menu-items/${id}`);
  assert.equal(getRes.status, 200);
  assert.equal(getRes.body.result.name, 'Full Styling');

  const patchRes = await owner.request('PATCH', `/v1/apps/demo/service-menu-items/${id}`, {
    durationMinutes: 60,
  });
  assert.equal(patchRes.status, 200);
  assert.equal(patchRes.body.result.durationMinutes, 60);

  const delRes = await owner.request('DELETE', `/v1/apps/demo/service-menu-items/${id}`);
  assert.equal(delRes.status, 200);
  assert.equal(delRes.body.result.archived, true);

  const afterGet = await owner.request('GET', `/v1/apps/demo/service-menu-items/${id}`);
  assert.equal(afterGet.status, 200);
  assert.equal(afterGet.body.result.status, 'ARCHIVED');
  await harness.close();
});

test('serviceMenuItem: validation failure returns 400 refusal', async () => {
  const harness = await setupHarness('demo');
  const owner = await harness.asRole('owner');

  const res = await owner.request('POST', '/v1/apps/demo/service-menu-items', {
    durationMinutes: 30,
  });
  assert.equal(res.status, 400);
  assert.equal(res.body.code, 'REFUSED');
  await harness.close();
});

test('serviceMenuItem: cross-tenant isolation (tenant B cannot see tenant A item)', async () => {
  const harness = await setupHarness('demo');
  const tenantA = await harness.asTenant('tenant-a', 'owner');
  const tenantB = await harness.asTenant('tenant-b', 'owner');

  const createRes = await tenantA.request('POST', '/v1/apps/demo/service-menu-items', {
    name: 'Tenant A Service',
    durationMinutes: 30,
  });
  assert.equal(createRes.status, 200);
  const id = createRes.body.result.id;

  const readB = await tenantB.request('GET', `/v1/apps/demo/service-menu-items/${id}`);
  assert.equal(readB.status, 404);
  await harness.close();
});

test('serviceMenuItem: cross-app isolation (another app token cannot call demo route)', async () => {
  const harness = await setupHarness('demo');
  const otherApp = await harness.asOtherApp('other-app');

  const res = await otherApp.request('GET', '/v1/apps/demo/service-menu-items');
  assert.equal(res.status, 404);
  await harness.close();
});

